const input = $input.first().json.body || {};
const url = input.url;
const fields = input.fields;

if (!url || typeof url !== 'string') {
  throw new Error('Send a JSON body with a "url" string.');
}
if (!Array.isArray(fields) || fields.length === 0) {
  throw new Error('Send a "fields" array, each entry with a name and a description.');
}

const schemaFields = fields.map(f => ({
  type: f.type || 'string',
  name: f.name,
  description: f.description || ''
}));

const action = {
  type: 'parse_json',
  output_type: 'inline',
  data_schema: {
    name: 'result',
    description: 'The requested fields extracted from the page',
    fields: schemaFields
  }
};

if (input.selector) {
  action.selector = input.selector;
}

const gaffaBody = {
  url,
  max_cache_age: 0,
  settings: {
    time_limit: 60000,
    actions: [action]
  }
};

return [{ json: { gaffaBody } }];
